export function mountEffectsEditor(pause){
 const b=document.createElement('button');b.id='effectsStudioButton';b.textContent='✧ Skill & VFX';const dialog=document.createElement('dialog');dialog.id='effectsStudioDialog';dialog.className='pet-mode-dialog';dialog.setAttribute('aria-label','Skill & VFX Studio');const frame=document.createElement('iframe');frame.title='Thiết kế kỹ năng và hiệu ứng';dialog.append(frame);document.body.append(dialog);document.querySelector('header nav').prepend(b);b.onclick=()=>{pause();dialog.showModal();if(!frame.src)frame.src=new URL('effects/index.html',location.href).href;else frame.contentWindow?.postMessage({type:'darkin.effects.resume'},location.origin)};window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===frame.contentWindow&&e.data?.type==='darkin.effects.close')dialog.close()});dialog.addEventListener('close',()=>frame.contentWindow?.postMessage({type:'darkin.effects.pause'},location.origin));
}
